mapper.select:
SELECT , c.CUSTOMER_NAME, r.DOCUMENT_NO
FROM TBL_AR_AGING_SNAPSHOT s
LEFT JOIN TBL_AR_CUSTOMER c ON s.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
LEFT JOIN TBL_AR_RECEIVABLE r ON s.RECEIVABLE_ID = r.RECEIVABLE_ID AND r.IS_DELETED = 0
WHERE 1=1

    AND s.ANALYSIS_DATE = #{param.analysisDate}


    AND s.CUSTOMER_ID = #{param.customerId}


    AND s.AGING_RANGE = #{param.agingRange}


    AND s.RISK_LEVEL = #{param.riskLevel}


    AND s.TENANT_ID = #{param.tenantId}

ORDER BY s.AGING_DAYS DESC

mapper.delete:
DELETE FROM TBL_AR_AGING_SNAPSHOT
WHERE ANALYSIS_DATE = #{analysisDate}
    AND TENANT_ID = #{tenantId}

mapper.select:
SELECT MAX(ANALYSIS_DATE)
FROM TBL_AR_AGING_SNAPSHOT
WHERE TENANT_ID = #{tenantId}

SELECT NVL(SUM(REMAINING_AMOUNT), 0)
FROM TBL_AR_AGING_SNAPSHOT
WHERE ANALYSIS_DATE = #{analysisDate}
    AND TENANT_ID = #{tenantId}
    AND AGING_DAYS > 0
